css:
#tongsci2-1-2-1-1-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-1-2-1-1-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-1-2-1-1-cover h1 { font-size: 112px; }
#tongsci2-1-2-1-1-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-1-2-1-1-cover .footer { left: 1100px; right: 300px; }
#tongsci2-1-2-1-1-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-1-2-1-1-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-1-2-1-1-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-1-2-1-1-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-1-2-1-1-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-1-2-1-1-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-1-2-1-1-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-1-2-1-1-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-1-2-1-1-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-1-2-1-1-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-1-2-1-1-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-1-2-1-1-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.1-2-1.1.cover */
(function () {
  'use strict';
  const { part } = window.Deck;
  const L1 = window.L1;
  const single = (btns) => btns.forEach((b) => b.addEventListener('click', () => {
    const on = b.getAttribute('aria-pressed') !== 'true';
    btns.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b)));
  }));
  // 체험 장: 기존 모듈의 «지금 할 것» 칩 글을 읽어 해 볼 일 ①②③을 맞춘다. map(글) → 지금 단계(없으면 앞 단계 유지)
  const DIG = '①②③④';
  function watch(root, sel, map) {
    const chip = root.querySelector(sel); if (!chip) return;
    const all = [...root.querySelectorAll('.u-steps li')].map((li) => +li.dataset.s);
    let cur = 1;
    const upd = () => {
      if (chip.classList.contains('done')) { L1.steps(root, 0, all); L1.done(root, true); return; }
      const t = chip.textContent.trim();
      let n = map ? map(t) : null;
      if (n == null) { const i = DIG.indexOf(t[0]); if (i >= 0) n = i + 1; }
      if (n != null) cur = n;
      L1.steps(root, cur, all.filter((k) => k < cur)); L1.done(root, false);
    };
    new MutationObserver(upd).observe(chip, { childList: true, characterData: true, subtree: true, attributes: true, attributeFilter: ['class'] });
    upd();
  }
  window.RxWatch = watch;
  // 3D 단계 장: 반응식 줄 밝히기
  const eqOn = (root, k, map) => root.querySelectorAll('.m3-eq[data-k]').forEach((p) => p.classList.toggle('on', map[p.dataset.k](k)));
  window.RxEqOn = eqOn;

  // 1. 표지: 세월 다이얼 + 예측(한 번 넘기면 «산소» 표시)
  part('tongsci2-1-2-1-1-cover', (root) => {
    window.RxSword.mount(root);
    single([...root.querySelectorAll('.share-opts button')]);
    const answer = (on) => { const b = root.querySelector('#pr-o2'); const was = b.classList.contains('rx-right'); b.classList.toggle('rx-right', on); if (on && !was) window.RxFx.burst(b); };
    return {
      fragment(f, on) { if (f.dataset.anim === 'rxans') answer(on); },
      sync(slide) { const f = slide.querySelector('[data-anim="rxans"]'); answer(!!f && f.classList.contains('visible')); },
    };
  });

  // 설명 장
})();
